#include <iostream>
#include <vector>
#include <algorithm>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N;
    cin >> N;

    vector<int> a(N);
    for (int &height : a) cin >> height;

    int hidden = 0;
    int maxHeight = 0;

    for (int i = N - 1; i >= 0; --i) {
        if (maxHeight >= a[i]) {
            ++hidden;
        }
        maxHeight = max(maxHeight, a[i]);
    }

    cout << hidden << '\n';
    return 0;
}
